import app from 'flarum/admin/app';
import Occasions from './Occasions';
const NS = 'ernestdefoe-fanfare';
const t = (key, params) => app.translator.trans(`${NS}.admin.settings.${key}`, params);
app.initializers.add(NS, () => {
  const data = app.data.fanfareAdmin || {};
  app.registry.for(NS).registerPermission({
    icon: 'fas fa-cake-candles',
    label: app.translator.trans(`${NS}.admin.permissions.view_people`),
    permission: `${NS}.viewPeople`,
    allowGuest: true
  }, 'view').registerPermission({
    icon: 'fas fa-gift',
    label: app.translator.trans(`${NS}.admin.permissions.wish`),
    permission: `${NS}.wish`
  }, 'reply').registerSetting(function () {
    return m(Occasions, {
      setting: this.setting(`${NS}.occasions`),
      data: data
    });
  }).registerSetting({
    type: 'html',
    html: m("h3", {
      className: "FanfareAdmin-heading"
    }, t('people_heading'))
  }).registerSetting({
    type: 'html',
    html: m("p", {
      className: "helpText"
    }, data.datlechin ? t('datlechin_help') : t('people_help'))
  }).registerSetting({
    setting: `${NS}.milestones`,
    type: 'boolean',
    label: t('milestones')
  }).registerSetting({
    setting: `${NS}.forum_birthday`,
    type: 'date',
    label: t('forum_birthday'),
    help: t('forum_birthday_help')
  }).registerSetting({
    type: 'html',
    html: m("h3", {
      className: "FanfareAdmin-heading"
    }, t('effects_heading'))
  }).registerSetting({
    type: 'html',
    html: m("p", {
      className: "helpText"
    }, t('effects_help'))
  }).registerSetting({
    setting: `${NS}.intensity`,
    type: 'select',
    label: t('intensity'),
    options: {
      subtle: t('intensity_subtle'),
      festive: t('intensity_festive'),
      full: t('intensity_full')
    },
    default: 'festive'
  }).registerSetting({
    setting: `${NS}.once_a_day`,
    type: 'boolean',
    label: t('once_a_day')
  }).registerSetting({
    setting: `${NS}.quiet_from`,
    type: 'time',
    label: t('quiet_from')
  }).registerSetting({
    setting: `${NS}.quiet_to`,
    type: 'time',
    label: t('quiet_to'),
    help: t('quiet_help')
  }).registerSetting({
    setting: `${NS}.timezone`,
    type: 'text',
    label: t('timezone'),
    help: t('timezone_help'),
    placeholder: data.timezone
  });
});